+		project.ID, project.LeadPaneID, project.LeadAbsentSince, cutoff)
+	if err != nil {
+		return false, err
+	}
+	changed, err := result.RowsAffected()
+	if err != nil || changed == 0 {
+		return false, err
+	}
+	if err := db.PersistProject(ctx, project.ID); err != nil {
+		return false, err
+	}
+	return true, nil
